class Solution:
    def longestPalindrome(self, s: str, t: str) -> int:
        max_len = 0
        n = len(s)
        m = len(t)

        # Try all substrings of s (including empty)
        for i in range(n + 1):
            for j in range(i, n + 1):
                s_sub = s[i:j]
                # Try all substrings of t (including empty)
                for k in range(m + 1):
                    for l in range(k, m + 1):
                        t_sub = t[k:l]
                        cand = s_sub + t_sub
                        if cand == cand[::-1]:
                            max_len = max(max_len, len(cand))
        return max_len
