from typing import List

class Solution:
    def minimumPairRemoval(self, nums: List[int]) -> int:
        ops = 0

        # Helper to check non-decreasing
        def is_non_decreasing(arr: List[int]) -> bool:
            for i in range(len(arr) - 1):
                if arr[i] > arr[i + 1]:
                    return False
            return True

        while not is_non_decreasing(nums):
            n = len(nums)
            min_sum = float('inf')
            min_idx = -1

            # Find adjacent pair with minimum sum (leftmost on tie)
            for i in range(n - 1):
                s = nums[i] + nums[i + 1]
                if s < min_sum:
                    min_sum = s
                    min_idx = i

            # Replace the chosen pair with their sum
            nums = nums[:min_idx] + [min_sum] + nums[min_idx + 2:]
            ops += 1

        return ops
