import sys

def solve() -> None:
    S = sys.stdin.readline().strip()
    pos = 0  # last matched position in the infinite pattern i,o,i,o,...
    for c in S:
        if c == 'i':
            # need an odd position > pos
            if pos % 2 == 0:
                pos += 1
            else:
                pos += 2
        else:  # c == 'o'
            # need an even position > pos
            if pos % 2 == 1:
                pos += 1
            else:
                pos += 2
    # final length must be even
    L = pos if pos % 2 == 0 else pos + 1
    print(L - len(S))

if __name__ == "__main__":
    solve()
